using System;

namespace TVM_Demo.Models
{
    /// <summary>
    /// Represents a payment transaction record generated by the Ticket Vendor Machine.
    /// </summary>
    public class Transaction
    {
        public int TransactionID { get; set; }
        public int DestinationID { get; set; }
        public string PaymentMethod { get; set; } = string.Empty; // 'CreditCard' or 'DigitalWallet'
        public string Status { get; set; } = string.Empty;        // 'Success' or 'Failed'
        public decimal Amount { get; set; }
        public DateTime CreatedAt { get; set; } = DateTime.Now;

        public bool IsSuccessful()
        {
            return string.Equals(Status, "Success", StringComparison.OrdinalIgnoreCase);
        }
    }
}
